class TestCreateObjectComponentViewComponent(BloomerpComponentTestCase):
    """Tests class `CreateObjectComponentView` from `bloomerp/components/objects/crud/create_update.py`."""

    view_name = 'components_create_object'

    def test_calendar_custom_composer_uses_the_shared_modal_component(self) -> None:
        """Dispatch a real clicked calendar cell to the composer without losing GET values or caller ID."""
        from django.urls import reverse
        inbox = Inbox.objects.create(user=self.admin_user, name="Composer inbox")
        self.client.force_login(self.admin_user)
        response = self.client.get(reverse("components_create_object", kwargs={
            "content_type_id": ContentType.objects.get_for_model(CalendarEvent).pk,
        }), {
            "start": "2026-10-15T09:00:00Z", "end": "2026-10-15T10:00:00Z",
            "inboxes": inbox.pk, "data_view_create_id": "clicked-calendar-cell",
        }, HTTP_HX_REQUEST="true", HTTP_HX_TARGET="create-object-modal-body")
        self.assertEqual(response.status_code, 200)
        self.assertNotIn("HX-Redirect", response)
        self.assertContains(response, 'id="calendar-event-create-form"')
        self.assertEqual(response.context["form"].initial["inbox"], inbox.pk)
        self.assertEqual(response.context["data_view_create_id"], "clicked-calendar-cell")

