    @staticmethod
    def custom_create(request: HttpRequest) -> HttpResponse:
        """Echo defaults to prove custom-view dispatch preserves the original modal request."""
        return JsonResponse({
            "start": request.GET.get("start"), "end": request.GET.get("end"),
            "caller": request.GET.get("data_view_create_id"),
        })

    def prepare_custom_create_view(self, scenario: RequestScenario) -> None:
        """Substitute a registered custom create callback at the component's routing boundary."""
        self.custom_create_override_patch = patch(
            "bloomerp.components.objects.crud.create_update.CreateObjectComponentView._create_view_is_overridden",
            return_value=True,
        )
        self.custom_create_resolve_patch = patch(
            "bloomerp.components.objects.crud.create_update.resolve",
            return_value=SimpleNamespace(func=self.custom_create, args=(), kwargs={}),
        )
        self.custom_create_override_patch.start()
        self.custom_create_resolve_patch.start()

    def cleanup_custom_create_view(self, scenario: RequestScenario) -> None:
        """Restore routing before the next declarative create-form scenario."""
        self.custom_create_resolve_patch.stop()
        self.custom_create_override_patch.stop()

    def no_refresh_or_create_event(self, response: HttpResponse) -> bool:
        """Ensure validation and explicit redirects do not complete a modal creation."""
        return "HX-Refresh" not in response and "HX-Trigger" not in response

    def created_for_data_view(self, response: HttpResponse) -> bool:
        """Verify immediate save feedback is delivered once with the list completion event."""
        events = json.loads(response["HX-Trigger"])
        detail = events["bloomerp:data-view-object-created"]
        queued_messages = detail["messages"]
        next_response = self.client.get(response.wsgi_request.path, HTTP_HX_REQUEST="true")
        return (
            "HX-Refresh" not in response
            and set(events) == {"bloomerp:data-view-object-created"}
            and detail["data_view_create_id"] == "list-opening"
            and len(queued_messages) == 1
            and queued_messages[0]["type"] == "success"
            and "New list label" in queued_messages[0]["text"]
            and "Object successfully created" in queued_messages[0]["text"]
            and "Object successfully created" not in next_response.content.decode()
            and Initiative.objects.filter(name="New list label").exists()
        )

    def created_for_foreign_field(self, response: HttpResponse) -> bool:
        """Keep nested foreign-field creation from closing or refreshing its parent list."""
        events = json.loads(response["HX-Trigger"])
        return (
            "HX-Refresh" not in response
            and set(events) == {"bloomerp:foreign-field-object-created"}
            and events["bloomerp:foreign-field-object-created"]["foreign_field_widget_id"]
            == "widget-parent"
        )

    def prepare_stale_layout(self, _scenario: RequestScenario) -> None:
        """Mix a customized Customer field with missing and foreign-model field IDs."""
        content_type = ContentType.objects.get_for_model(self.CustomerModel)
        field = ApplicationField.objects.get(content_type=content_type, field="first_name")
        other_field = ApplicationField.objects.get(
            content_type=ContentType.objects.get_for_model(Initiative), field="name",
        )
        self.layout_preference = PreferenceManager(self.admin_user).get_or_create_selected(
            UserObjectLayoutPreference, scope={"content_type_id": content_type.pk},
        )
        self.saved_layout = {"rows": [{
            "title": "Custom section",
            "columns": 3,
            "items": [
                {"id": str(field.pk), "colspan": 2, "config": {"label": "Retained field"}},
                {"id": "2147483647"},
                {"id": other_field.pk},
            ],
        }]}
        self.layout_preference.layout = self.saved_layout
        self.layout_preference.save(update_fields=["layout"])

    def prepare_fully_stale_layout(self, scenario: RequestScenario) -> None:
        """Leave a nonempty saved layout whose field IDs no longer resolve."""
        self.prepare_stale_layout(scenario)
        self.saved_layout["rows"][0]["items"] = [{"id": "2147483647"}]
        self.layout_preference.layout = self.saved_layout
        self.layout_preference.save(update_fields=["layout"])

    def layout_remains_saved(self, _response: HttpResponse) -> bool:
        """Ensure render-time recovery never overwrites the user's saved layout."""
        self.layout_preference.refresh_from_db()
        return self.layout_preference.layout == self.saved_layout
